import Link from 'next/link'
import { getCatalogProducts } from '@/lib/catalog'

export default async function InventorySummaryPage() {
  const { products, revision, lastSyncedAt } = await getCatalogProducts()
  const available = products.filter((p) => p.available).length
  const totalStock = products.reduce((sum, p) => sum + p.stock, 0)

  return (
    <div style={{ maxWidth: 720, margin: '0 auto', padding: '32px 20px', fontFamily: 'system-ui, sans-serif' }}>
      <p style={{ margin: 0, fontSize: 13 }}>
        <Link href="/admin/catalog" style={{ color: '#2563eb' }}>
          ← Back to catalog
        </Link>
      </p>
      <h1 style={{ margin: '16px 0 8px', fontSize: 26, fontWeight: 650 }}>Inventory summary</h1>
      <p style={{ margin: '0 0 24px', color: '#475569', lineHeight: 1.5 }}>
        This page calls the same <code>getCatalogProducts()</code> helper, so when the catalog sync finishes and tag{' '}
        <code>products</code> is revalidated, both views eventually serve the same fresh snapshot.
      </p>
      <ul style={{ listStyle: 'none', padding: 0, margin: 0, fontSize: 15, lineHeight: 2 }}>
        <li>
          <strong>SKUs:</strong> {products.length.toLocaleString()}
        </li>
        <li>
          <strong>Available listings:</strong> {available.toLocaleString()}
        </li>
        <li>
          <strong>Total units in stock:</strong> {totalStock.toLocaleString()}
        </li>
        <li>
          <strong>Revision:</strong> {revision}
        </li>
        <li>
          <strong>Snapshot from:</strong> {new Date(lastSyncedAt).toLocaleString()}
        </li>
      </ul>
    </div>
  )
}

